triage = analyse(message, history)
if triage.immediate_danger:
    return emergency_protocol()
if triage.ambiguous_safety_signal:
    return direct_safety_question()
if triage.self_harm_risk:
    assess(intent, plan, means, timeframe)
if triage.threat_to_others:
    assess(target, intent, means, timeframe)
if triage.abuse_or_medical_risk:
    run_specialist_pathway()
return emotional_distress_classification()
